from pathlib import Path
p=Path(__file__).parent;w=p/'work/profile'
exec((p/'prepare-profile-single-initial.py').read_text(),{'__file__':str(p/'prepare-profile-single-initial.py')})
f=w/'hip_reference_network.h';s=f.read_text();a=s.index(' struct AuditEvent{');b=s.index(' U ModelMode()const',a)
code=r'''
 struct AuditEvent{std::string name;bool timed=false;};
 std::map<Handle,std::string> audit_names;std::vector<AuditEvent> audit_events;bool audit_enabled=false;size_t audit_cursor=0,audit_epoch=0;unsigned audit_stride=0;Handle audit_module=nullptr,audit_stamp=nullptr;void*audit_data=nullptr;
 void AuditStamp(unsigned slot){void*args[]={&audit_data,&slot};api.Check(api.hipModuleLaunchKernel(audit_stamp,1,1,1,1,1,1,0,stream,args,nullptr),"device realtime stamp");}
 size_t AuditStart(Handle function){if(!audit_enabled)return size_t(-1);if(!audit_names.count(function)){for(const auto&entry:functions)if(entry.second==function){audit_names.emplace(function,entry.first);break;}}if(!audit_names.count(function))throw std::runtime_error("audit physical symbol missing");const auto&name=audit_names.at(function);size_t k=audit_cursor++;if(k==audit_events.size())audit_events.push_back({name,false});auto&e=audit_events[k];if(e.name!=name)throw std::runtime_error("audit dispatch sequence changed");e.timed=k==((audit_epoch-1)%audit_stride);if(e.timed)AuditStamp(0);return k;}
 void AuditStop(size_t k){if(k!=size_t(-1)&&audit_events[k].timed)AuditStamp(1);}
 int AuditLaunch(Handle f,unsigned gx,unsigned gy,unsigned gz,unsigned bx,unsigned by,unsigned bz,unsigned smem,Handle st,void**args,void**extra){size_t k=AuditStart(f);int rc=api.hipModuleLaunchKernel(f,gx,gy,gz,bx,by,bz,smem,st,args,extra);AuditStop(k);return rc;}
 void AuditBegin(){if(!audit_stride){const char*v=std::getenv("PHASE4_DISPATCHES");if(!v)throw std::runtime_error("audit expected count missing");audit_stride=std::stoul(v);const char*path=std::getenv("PHASE4_STAMP_MODULE");if(!path)throw std::runtime_error("stamp module missing");api.Check(api.hipModuleLoad(&audit_module,path),"load timestamp module");api.Check(api.hipModuleGetFunction(&audit_stamp,audit_module,"phase4_stamp"),"timestamp function");api.Check(api.hipMalloc(&audit_data,32),"timestamp storage");}audit_enabled=true;audit_cursor=0;++audit_epoch;AuditStamp(2);}
 void AuditFrameEnd(){if(audit_enabled)AuditStamp(3);}
 void AuditWrite(FILE*f,unsigned frame){if(audit_cursor!=audit_stride)throw std::runtime_error("audit total dispatch count mismatch actual="+std::to_string(audit_cursor)+" expected="+std::to_string(audit_stride));unsigned long long t[4]{};api.Check(api.hipMemcpy(t,audit_data,32,2),"timestamp readback");if(!(t[0]<=t[1]&&t[2]<=t[0]&&t[1]<=t[3]&&t[2]<t[3]))throw std::runtime_error("nonmonotonic device realtime clock");for(size_t k=0;k<audit_cursor;k++){auto&e=audit_events[k];if(f&&e.timed)fprintf(f,"%u,%zu,%s,%llu,%llu,%llu,%llu,%zu\n",frame,k,e.name.c_str(),t[0],t[1],t[2],t[3],audit_cursor);}if(f)fflush(f);}
 void AuditClose(){audit_enabled=false;if(audit_data)api.hipFree(audit_data);if(audit_module)api.hipModuleUnload(audit_module);}
'''
f.write_text(s[:a]+code+s[b:])
f=w/'profile.cpp';s=f.read_text().replace('if(!profiling)api.Check(', 'api.Check(').replace('if(!profiling&&(!std::isfinite(ms)||ms<=0||ms>10000))','if(!std::isfinite(ms)||ms<=0||ms>10000)');s=s.replace('frame,dispatch,kernel,gpu_ms,dispatches_total','frame,dispatch,kernel,begin_tick,end_tick,network_begin_tick,network_end_tick,dispatches_total');s=s.replace('net.Enqueue(in,nullptr,out,0);net.Synchronize();','net.Enqueue(in,nullptr,out,0);if(profiling)net.AuditFrameEnd();net.Synchronize();').replace('net.Enqueue(in,nullptr,out,0);api.Check(api.hipEventRecord(end,stream)','net.Enqueue(in,nullptr,out,0);if(profiling)net.AuditFrameEnd();api.Check(api.hipEventRecord(end,stream)');f.write_text(s)
