cal=r'''if(profiling&&std::getenv("PHASE4_CLOCK_CALIBRATE")){std::ofstream cf(std::string(argv[5])+"/clock-calibration.csv");cf<<"repeats,ticks,gpu_ms,cpu_ms\n";net.audit_enabled=false;for(unsigned n:{8u,32u,64u,128u}){auto ca=std::chrono::steady_clock::now();api.Check(api.hipEventRecord(begin,stream),"clock begin");net.AuditStamp(2);for(unsigned j=0;j<n;j++)net.Enqueue(in,nullptr,out,0);net.AuditStamp(3);api.Check(api.hipEventRecord(end,stream),"clock end");net.Synchronize();auto cb=std::chrono::steady_clock::now();float gm;api.Check(api.hipEventElapsedTime(&gm,begin,end),"clock elapsed");unsigned long long tv[4];api.Check(api.hipMemcpy(tv,net.audit_data,32,2),"clock readback");cf<<n<<','<<(tv[3]-tv[2])<<','<<gm<<','<<std::chrono::duration<double,std::milli>(cb-ca).count()<<'\n';}net.audit_enabled=true;std::ofstream of(std::string(argv[5])+"/stamp-overhead.csv");of<<"ticks\n";for(unsigned j=0;j<100;j++){net.AuditStamp(0);net.AuditStamp(1);net.Synchronize();unsigned long long tv[4];api.Check(api.hipMemcpy(tv,net.audit_data,32,2),"stamp overhead readback");of<<(tv[1]-tv[0])<<'\n';}}'''
assert key in s;s=s.replace(key,cal+key);f.write_text(s)
